export function drawCheckpointArt(g,item,cam,time){const x=Math.round(item.x-cam),glow=item.active&&Math.floor(time*8)%2;box(g,x,364,9,106,'#75512d');px(g,x+3,369,3,92,'#c0894b');poly(g,[[x+9,370],[x+53,378],[x+39,405],[x+9,396]],glow?'#fff083':'#f2bd32');px(g,x+15,380,25,4,'#fff3a5');box(g,x-6,456,22,14,'#686452','#313533')}
export function drawBottleEffect(g,s,cam,time){const x=Math.round(s.x-cam),y=Math.round(s.y),col=s.type==='frost'?'#55dff2':s.type==='ember'?'#f26445':'#f0d94c';box(g,x,y,11,13,col);px(g,x+3,y+2,4,4,'#fff5c9');for(let i=0;i<3;i++)px(g,x-5-i*4,y+5+((i+Math.floor(time*12))%3)*3,3,3,col)}
export function drawFreedArt(g,e,cam,visual){const x=Math.round(e.x-cam),y=Math.round(e.y),fv=freedVisualVariant(visual,e.type,e.evacDir);if(e.type==='animal'){blob(g,[[x+1,y+25],[x+6,y+18],[x+25,y+16],[x+35,y+20],[x+e.w-2,y+25],[x+e.w-8,y+36],[x+10,y+38]],'#a97848','#4d352c');poly(g,[[x+29,y+20],[x+38,y+6],[x+47,y+19]],'#c0935f');px(g,x+39+fv.eyeShift,y+15,3,3,P.o);for(const lx of[8,29])blob(g,[[x+lx,y+34],[x+lx+8,y+34],[x+lx+7,y+e.h-1],[x+lx+1,y+e.h]],'#68432e','#493227')}else{blob(g,[[x+e.w/2-10,y+6],[x+e.w/2-7,y+2],[x+e.w/2+8,y+3],[x+e.w/2+11,y+9],[x+e.w/2+8,y+20],[x+e.w/2-8,y+21]],P.skin,'#4d332d');px(g,x+e.w/2-5+fv.eyeShift,y+11,3,3,P.o);px(g,x+e.w/2+4+fv.eyeShift,y+11,2,2,'#fff');blob(g,[[x+9,y+25],[x+14,y+22],[x+e.w-14,y+22],[x+e.w-8,y+28],[x+e.w-11,y+48],[x+12,y+48]],e.type==='boss'?'#c4b794':'#b96643','#4d332d');blob(g,[[x+10,y+47],[x+20,y+47],[x+19,y+62],[x+11,y+62]],P.leather,'#493227');blob(g,[[x+e.w-20,y+47],[x+e.w-10,y+47],[x+e.w-11,y+62],[x+e.w-19,y+62]],P.leather,'#493227')}if(fv.speech)bubble(g,x+e.w/2,y-2,fv.speech)}
